#include "harness.h"
#include "pathfold.h"

int main(void) {
    char out[64];
    h_init();

    CHECK_INT(pf_normalize("/srv/./data//logs/", 18, out, sizeof out, 0), 14);
    CHECK_STR(out, "/srv/data/logs");
    CHECK_INT(pf_normalize("a/b/../../c", 11, out, sizeof out, 0), 1);
    CHECK_STR(out, "c");
    CHECK_INT(pf_normalize("/../etc", 7, out, sizeof out, 0), 4);
    CHECK_STR(out, "/etc");
    return h_report();
}

